// ina219_fast_demo.ino -- Arduino Mega 2560
//
// Requires ina219_fast.S to sit next to this file in the same sketch folder.
// The .S is assembled by the Arduino builder and linked with the sketch.
//
// The sampler runs in assembly; this sketch only prints the raw 16-bit values
// and shows the scaling for the default configuration.

#include <Arduino.h>

extern "C" {
  void     ina219_init(void);    // TWI 400 kHz + configure INA219
  void     ina219_sample(void);  // blocking: returns after one fresh sample
  void     ina219_run(void);     // never returns; calls ina219_sample forever

  extern volatile uint16_t ina_shunt;    // raw shunt  voltage (10 uV / LSB, signed)
  extern volatile uint16_t ina_bus;      // raw bus    voltage (bit15..3, 4 mV / LSB)
  extern volatile uint16_t ina_current;  // raw current (current_LSB / LSB, signed)
  extern volatile uint16_t ina_power;    // raw power
  extern volatile uint8_t  ina_head;     // ring buffer index (0..255)
  extern volatile uint32_t ina_count;    // number of samples captured
  extern volatile uint16_t ina_buf[256]; // ring buffer of raw shunt samples
}

void setup() {
  Serial.begin(115200);
  ina219_init();
}

void loop() {
  ina219_sample();                 // ~68 ms per call at 12-bit/128-avg

  int16_t sh = (int16_t)ina_shunt;
  int16_t cu = (int16_t)ina_current;
  uint16_t bus = (uint16_t)ina_bus;
  uint16_t pw  = (uint16_t)ina_power;

  // Scaling for INA_CAL = 4096 with a 0.1 ohm shunt:
  //   shunt  : 10 uV/LSB
  //   bus    : 4 mV/LSB  (field = bus >> 3)
  //   current: 100 uA/LSB
  //   power  : 20 * current_LSB = 2 mW/LSB
  Serial.print(F("n="));    Serial.print(ina_count);
  Serial.print(F("  shunt="));   Serial.print(sh * 10);      Serial.print(F(" uV"));
  Serial.print(F("  bus="));     Serial.print((bus >> 3) * 4); Serial.print(F(" mV"));
  Serial.print(F("  I="));       Serial.print(cu * 0.1f, 2);  Serial.print(F(" mA"));
  Serial.print(F("  P="));       Serial.print(pw * 2);        Serial.println(F(" mW"));
}

